import sys; sys.path.insert(0,'work'); sys.path.insert(0,'.')
import numpy as np, tools
from build import build, embed, N46
L=tools.states('states_L2.npz'); Y=L['obs'].astype(float)
src=tools.load('source_weights_L2.npz')
for mode in 'ABC':
  w,_=build(1.0, mode)
  Xe=embed(Y,1.0,mode)
  # overwrite N/S stop-line with raw L2 values (s=1, pure copy) to isolate the E/W mapping
  for k in ('q','d'):
    for ap in 'NS':
      for ln in range(3):
        Xe[:, tools.names().index(f'{k}_{ap}{ln}')] = Y[:, N46.index(f'{k}_{ap}{ln}')]
  print(mode, 'max|logit diff|', np.abs(tools.forward(w,Xe)-tools.forward(src,Y)).max())
"

